(function () { 'use strict'; document.addEventListener('DOMContentLoaded', function () { initStickyAddToCart(); initSkeletonLoaders(); initImageHoverZoom(); initFreeShippingProgress(); initPageTransitions(); }); function initStickyAddToCart() { const mainBtn = document.querySelector('.main-buy-button'); const stickyBtn = document.querySelector('.sticky-buy-wrapper'); if (!mainBtn || !stickyBtn) return; const observer = new IntersectionObserver((entries) => { entries.forEach((entry) => { if (!entry.isIntersecting && window.scrollY > 300) { stickyBtn.classList.add('visible'); } else { stickyBtn.classList.remove('visible'); } }); }, { threshold: 0 }); observer.observe(mainBtn); window.addEventListener('scroll', () => { const rect = mainBtn.getBoundingClientRect(); if (rect.top < 0 && window.scrollY > 300) { stickyBtn.classList.add('visible'); } else { stickyBtn.classList.remove('visible'); } }, { passive: true }); } function initSkeletonLoaders() { const images = document.querySelectorAll('.skeleton img, .product-image-skeleton img'); images.forEach((img) => { const parent = img.parentElement; if (!parent) return; if (img.complete) { parent.classList.remove('skeleton', 'product-image-skeleton'); } else { img.addEventListener('load', () => { parent.classList.remove('skeleton', 'product-image-skeleton'); }, { once: true }); } }); } function initImageHoverZoom() { const containers = document.querySelectorAll('.hover-zoom-container'); containers.forEach((container) => { const img = container.querySelector('img'); if (!img) return; container.addEventListener('mousemove', (event) => { const rect = container.getBoundingClientRect(); if (rect.width <= 0 || rect.height <= 0) return; const xPercent = ((event.clientX - rect.left) / rect.width) * 100; const yPercent = ((event.clientY - rect.top) / rect.height) * 100; img.style.transformOrigin = `${xPercent}% ${yPercent}%`; img.style.transform = 'scale(1.5)'; }); container.addEventListener('mouseleave', () => { img.style.transform = 'scale(1)'; img.style.transformOrigin = 'center center'; }); }); } function initFreeShippingProgress() { const bars = document.querySelectorAll('.free-shipping-progress-bar'); const texts = document.querySelectorAll('.free-shipping-text'); const cartTotalEl = document.querySelector('.cart-subtotal-value'); const markers = document.querySelectorAll('[data-free-shipping-marker]'); if (!bars.length || !cartTotalEl) return; const wrappers = Array.from(bars).map((bar) => ( bar.closest('.free-shipping-progress-wrapper, .free-shipping-rewards, .gamification-rewards-container') || bar )); texts.forEach((text) => { text.textContent = ''; }); wrappers.forEach((wrapper) => { wrapper.style.display = 'none'; }); markers.forEach((marker) => { marker.style.display = 'none'; }); fetch('/api/settings/free-shipping.php', { cache: 'no-store' }) .then((response) => { if (!response.ok) throw new Error('free_shipping_config_http_' + response.status); return response.json(); }) .then((config) => { const limit = Number(config && config.threshold); if (!config || !config.enabled || !Number.isFinite(limit) || limit <= 0) { return; } wrappers.forEach((wrapper) => { wrapper.style.display = ''; }); markers.forEach((marker) => { marker.style.display = 'flex'; }); window.updateFreeShippingVisual = function () { const totalString = cartTotalEl.innerText .replace('R$', '') .replace(/\./g, '') .replace(',', '.') .trim(); const currentTotal = Math.max(0, parseFloat(totalString) || 0); const percentage = Math.min(100, (currentTotal / limit) * 100); bars.forEach((bar) => { bar.style.width = `${percentage}%`; bar.classList.toggle('bg-success', currentTotal >= limit); }); texts.forEach((text) => { if (currentTotal >= limit) { text.innerHTML = '🎉 Parabéns! Você ganhou <strong>Frete Grátis</strong>!'; return; } const remaining = (limit - currentTotal).toFixed(2).replace('.', ','); text.innerHTML = `Faltam apenas <strong>R$ ${remaining}</strong> para você ganhar <strong>Frete Grátis!</strong>`; }); }; window.updateFreeShippingVisual(); }) .catch(() => { }); } function initPageTransitions() { document.body.classList.add('page-loaded'); } })();